package ch.jalu.configme.configurationdata;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

@RunWith(MockitoJUnitRunner.class)
public class PropertyListBuilderTest {

    @Mock
    private List<Property<?>> properties;

    @Test
    public void create_EmptyProperties_ReturnsEmptyList() {
        assert 0 == new PropertyListBuilder().create().size();
    }

    @Test
    public void add_AddsSingleProperty_ReturnsUpdatedList() {
        new PropertyListBuilder()
                .add(new Property<String>("key", "value"))
                .create()
                .forEach(property -> assertEquals("key", property.getKey()));
    }

    @Test
    public void create_MultipleProperties_ReturnsUpdatedList() {
        List<Property<?>> expectedProperties = new ArrayList<>();
        expectedProperties.add(new Property<String>("key1", "value1"));
        expectedProperties.add(new Property<String>("key2", "value2"));

        new PropertyListBuilder()
                .add(expectedProperties.get(0))
                .add(expectedProperties.get(1))
                .create()
                .forEach(property -> assertEquals("key1", property.getKey()));
    }

    @Test
    public void add_DuplicateProperty_ThrowsConfigMeException() {
        Mockito.doThrow(ConfigMeException.class)
                .when(new Property<String>("key", "value"))
                .getKey();

        assert ConfigMeException.class.isInstance(new PropertyListBuilder().add(new Property<String>("key", "value")).create());
    }

    @Test
    public void getRootEntries_ReturnsEmptyMap() {
        assertEquals(0, new PropertyListBuilder().getRootEntries().size());
    }
}

class PropertyListBuilder {
    private List<Property<?>> properties = new ArrayList<>();

    public void add(Property<?> property) {
        if (property.getKey() == null || property.getValue() == null) {
            throw new ConfigMeException("Property is invalid");
        }

        properties.add(property);
    }

    public List<Property<?>> create() {
        return properties;
    }

    protected final Map<String, Object> getRootEntries() {
        return Collections.emptyMap();
    }
}
